using LSPD_First_Response.Mod.Callouts;
namespace PatrolsCallouts.Callouts { [CalloutInfo("SuspiciousObjectFound", CalloutProbability.Medium)] public sealed class SuspiciousObjectFound : ScenarioCalloutBase { protected override string DispatchName { get { return "Suspicious object found"; } } protected override string DispatchAdvisory { get { return "A passerby found an unattended bag in a public area."; } } protected override string SceneTitle { get { return "SUSPICIOUS OBJECT"; } } protected override string InitialBriefing { get { return "Secure the area and inspect the reported object."; } } protected override string InterviewText { get { return "I did not touch it. It has been sitting here for several minutes."; } } protected override string EvidenceText { get { return "The bag contains personal items and no immediate hazard is visible."; } } protected override bool HasWitness { get { return true; } } } }
